type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 10, 0, clk, true},
		{"negative rate", 10, -1, clk, true},
		{"valid", 10, 2, clk, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	clk := newFakeClock()
	b, err := New(5, 10, clk) // 10 tokens/sec
	if err != nil {
		t.Fatal(err)
	}

	if !b.AllowN(5) {
		t.Fatal("expected 5 tokens")
	}
	if b.AllowN(1) {
		t.Fatal("expected bucket empty")
	}
	if !b.AllowN(0) {
		t.Fatal("zero should be allowed")
	}
	if b.AllowN(-1) {
		t.Fatal("negative should be denied")
	}

	clk.Advance(100 * time.Millisecond) // +1 token
	if !b.AllowN(1) {
		t.Fatal("expected refilled token")
	}
	if b.AllowN(1) {
		t.Fatal("expected empty again")
	}

	clk.Advance(time.Second) // +10, capped at 5
	if got := b.Tokens(); got != 5 {
		t.Fatalf("tokens = %v, want 5", got)
	}
}

func TestAllowNPartialRefill(t *testing.T) {
	clk := newFakeClock()
	b, err := New(2, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(2) {
		t.Fatal("expected initial tokens")
	}
	clk.Advance(1500 * time.Millisecond) // +1.5
	if !b.AllowN(1) {
		t.Fatal("expected one token")
	}
	if b.AllowN(1) {
		t.Fatal("expected only 0.5 left")
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock()
	b, err := New(100, 1000, clk)
	if err != nil {
